{
  "name": "fixture_plan",
  "description": "Offline plan for related test data across Postgres databases and Kafka. Reads cached schemas, FKs and usage indexes first. Seeds use explicit db/schema.table and equality filters. Follows schema FKs; cross-database joins are explicit relations. Returns candidates for review, never guesses them as facts. Inspect then pass the inputs to fixture_capture.",
  "group": "code",
  "origin": "built-in",
  "execution": {
    "protocol": "dt.tool/v1",
    "transport": "in-process"
  },
  "inputSchema": {
    "type": "object",
    "properties": {
      "env": {
        "type": "string",
        "enum": [
          "dev"
        ],
        "default": "dev",
        "description": "Environment"
      },
      "service": {
        "type": "string",
        "description": "Service whose usage informs candidates"
      },
      "seeds": {
        "type": "array",
        "items": {
          "type": "object",
          "additionalProperties": true
        },
        "description": "Roots: [{db, table:\"sales.orders\", where:{id:42}}]"
      },
      "relations": {
        "type": "array",
        "items": {
          "type": "object",
          "additionalProperties": true
        },
        "description": "Cross-DB relationships: [{from:{db,table,columns:[...]},to:{db,table,columns:[...]},required:true,evidence:\"file:line\"}]"
      },
      "topics": {
        "type": "array",
        "items": {
          "type": "object",
          "additionalProperties": true
        },
        "description": "Topics: [{topic,matches:[{path:\"value.orderId\",from:{db,table,column:\"id\"}}],match:\"all|any\",offsets:{partition:offset}}]"
      },
      "limits": {
        "type": "object",
        "additionalProperties": true,
        "description": "depth, rowsPerTable, totalRows, messagesPerTopic, totalMessages, queries"
      },
      "includeChildren": {
        "type": "boolean",
        "default": false,
        "description": "Also follow reverse FKs (bounded); default only required parents"
      }
    },
    "required": []
  }
}
